import os, json, csv, math
import numpy as np
from collections import defaultdict

DATA_BASE = "storage/shared/agency_lab/data"
ANAL_BASE = "storage/shared/agency_lab/analyses"
CSV_DIR = os.path.join(ANAL_BASE, "csv")
os.makedirs(ANAL_BASE, exist_ok=True)
os.makedirs(CSV_DIR, exist_ok=True)

# ---------- Loader (robust) ----------
def find_export_files():
    files = []
    top = os.path.join("storage/shared/agency_lab", "axiom_rng_actions_v1_2b_interactions.json")
    if os.path.exists(top):
        files.append(top)
    for root, _, fnames in os.walk(DATA_BASE):
        for fn in fnames:
            if fn.endswith(".json"):
                files.append(os.path.join(root, fn))
    return files

def infer_lineage_from_path(path):
    p = path.replace("\\", "/").split("/")
    if "lineage_exports" in p:
        i = p.index("lineage_exports")
        if i + 1 < len(p):
            seg = p[i+1]
            if seg.endswith("_exports"):
                return seg[:-len("_exports")].rstrip("_").lower()
    return None

def infer_lineage_from_agent(agent_id):
    s = str(agent_id) if agent_id is not None else ""
    for sep in ["_", " "]:
        if sep in s and s.split(sep)[0]:
            return s.split(sep)[0].lower().rstrip("_")
    return (s.lower().rstrip("_") if s else "unknown")

def coerce_actions_payload(payload):
    if isinstance(payload, dict):
        acts = payload.get("actions")
        if isinstance(acts, list): return acts, payload.get("lineage")
        for k in ("data","items"):
            v = payload.get(k)
            if isinstance(v, list): return v, payload.get("lineage")
        return [payload], payload.get("lineage")
    elif isinstance(payload, list):
        return payload, None
    return [], None

def load_actions():
    actions = []
    for path in find_export_files():
        try:
            with open(path, "r", encoding="utf-8") as f:
                payload = json.load(f)
        except Exception:
            continue
        acts, payload_lineage = coerce_actions_payload(payload)
        path_lin = infer_lineage_from_path(path)
        for a in acts:
            if not isinstance(a, dict): continue
            agent_id = a.get("agent_id") or a.get("agent") or a.get("source_agent")
            action_type = a.get("action_type") or a.get("type")
            if not agent_id or not action_type: continue
            tick = a.get("tick")
            try: tick = int(tick) if tick is not None else None
            except Exception: tick = None
            lineage = a.get("lineage") or payload_lineage or path_lin or infer_lineage_from_agent(agent_id) or "unknown"
            target = a.get("target")
            if target is not None: target = str(target)
            actions.append({
                "agent_id": str(agent_id),
                "action_type": str(action_type),
                "tick": tick,
                "lineage": str(lineage).lower(),
                "target": target,
            })
    return [a for a in actions if a.get("tick") is not None]

# ---------- Rolling with emergence (W=5, step=1) ----------
def build_first_occurrence(actions):
    # Map type -> (first_tick, lineage)
    first = {}
    for a in sorted(actions, key=lambda x: x["tick"]):
        t = a["action_type"]
        if t not in first:
            first[t] = (a["tick"], a["lineage"])
    return first

def rolling_metrics(actions, W=5, step=1):
    if not actions: return []
    persistent_types = {"create","build","generate","store","initialize","save","write"}
    agents_all = {a["agent_id"] for a in actions}
    min_t = min(a["tick"] for a in actions)
    max_t = max(a["tick"] for a in actions)

    first = build_first_occurrence(actions)

    # Pre-bucket actions by tick for speed
    by_tick = defaultdict(list)
    for a in actions:
        by_tick[a["tick"]].append(a)

    rows = []
    t = min_t
    while t <= max_t:
        start, end = t, t + W - 1
        # gather window actions
        win = []
        for tt in range(start, end+1):
            win.extend(by_tick.get(tt, []))
        if win:
            # cumulative unique types up to end
            cum_types = sum(1 for tp, (ft, _) in first.items() if ft <= end)
            # new types credited per lineage in this window: those whose first occurrence is inside [start,end]
            new_credit = defaultdict(int)
            for tp, (ft, lin) in first.items():
                if start <= ft <= end:
                    new_credit[lin] += 1

            # per-lineage persistence/collab/emergence
            win_agent_ids = {a["agent_id"] for a in win}
            by_lin = defaultdict(list)
            for a in win:
                by_lin[a["lineage"]].append(a)

            for lin, lst in by_lin.items():
                n = len(lst)
                if n == 0:
                    pr = ci = er = 0.0
                else:
                    pers = sum(1 for a in lst if a["action_type"] in persistent_types)
                    inter = sum(1 for a in lst if (a.get("target") in win_agent_ids))
                    pr = pers / n
                    ci = inter / (2*n)
                    er = (new_credit.get(lin, 0) / max(1, cum_types)) if cum_types is not None else 0.0
                rows.append([lin, start, end, n, f"{pr:.6f}", f"{ci:.6f}", f"{er:.6f}"])
        t += step
    return rows

# ---------- 3-var VAR block Granger ----------
def series_by_lineage_from_rows(rows):
    # rows: [lin, start, end, actions, pr, ci, er]
    by_lin = defaultdict(list)
    for r in rows:
        lin, start = r[0], int(r[1])
        pr = float(r[4]); ci = float(r[5]); er = float(r[6])
        by_lin[lin].append((start, (pr, ci, er)))
    for lin in by_lin:
        by_lin[lin].sort(key=lambda x: x[0])
    return by_lin

def align_pair_3(sa, sb, P, min_len=14):
    if sa is None or sb is None: return None
    ka = {k:v for k,v in sa}
    kb = {k:v for k,v in sb}
    common = sorted(set(ka.keys()) & set(kb.keys()))
    if len(common) < max(min_len, P+8): return None
    A = np.array([ka[k] for k in common], dtype=float)  # T x 3
    B = np.array([kb[k] for k in common], dtype=float)
    if A.ndim!=2 or B.ndim!=2 or A.shape[1]!=3 or B.shape[1]!=3: return None
    return A, B

def lag_stack(X, P):
    T, d = X.shape
    Z = []
    for p in range(1, P+1):
        Z.append(X[P-p:T-p, :])
    return np.concatenate(Z, axis=1) if Z else None

def ols_SSE(X, y):
    XtX = X.T @ X
    try:
        beta = np.linalg.solve(XtX, X.T @ y)
    except np.linalg.LinAlgError:
        beta = np.linalg.pinv(XtX) @ (X.T @ y)
    resid = y - X @ beta
    return float(resid.T @ resid)

def block_granger_VAR(A, B, P):
    # A: T x 3 (effect), B: T x 3 (cause)
    if A is None or B is None: return None
    if A.shape[0] <= P + 8: return None
    endog = lag_stack(A, P); exog = lag_stack(B, P)
    if endog is None or exog is None: return None
    N = A.shape[0] - P
    ones = np.ones((N,1), dtype=float)
    Xr = np.concatenate([ones, endog], axis=1)            # 1 + 3P
    Xu = np.concatenate([ones, endog, exog], axis=1)      # 1 + 6P
    Y = A[P:,:]                                           # N x 3
    if Y.shape[0] != N: return None

    SSE_r = SSE_u = 0.0
    for j in range(3):
        yj = Y[:, j]
        SSE_r += ols_SSE(Xr, yj)
        SSE_u += ols_SSE(Xu, yj)

    k_r = Xr.shape[1]; k_u = Xu.shape[1]; d = 3
    df1 = (k_u - k_r) * d
    df2 = d*N - d*k_u
    if df2 <= 0 or SSE_u <= 0:
        F = float('nan'); pval = None
    else:
        num = (SSE_r - SSE_u) / df1
        den = SSE_u / df2
        F = float(num / den) if den > 0 else float('inf')
        pval = None
        try:
            import scipy.stats as st  # type: ignore
            pval = float(st.f.sf(F, df1, df2))
        except Exception:
            pval = None
    AIC_r = N * math.log((SSE_r / max(N,1))) + 2 * (k_r * d) if SSE_r > 0 else float('-inf')
    AIC_u = N * math.log((SSE_u / max(N,1))) + 2 * (k_u * d) if SSE_u > 0 else float('-inf')
    dAIC = AIC_u - AIC_r
    return {"F": F, "pvalue": pval, "df1": int(df1), "df2": int(df2), "dAIC": dAIC}

def main():
    actions = load_actions()
    if not actions:
        print("ERROR", "NO_ACTIONS")
        return 0
    # Rolling step=1
    roll_rows = rolling_metrics(actions, W=5, step=1)
    # Save rolling with emergence
    roll_csv = os.path.join(CSV_DIR, "joint_metrics_v2_8_per_lineage_rolling.csv")
    with open(roll_csv, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(["lineage","start","end","actions","persistence_rate","collaboration_index","emergence_rate"])
        for r in roll_rows:
            w.writerow(r)

    by_lin = series_by_lineage_from_rows(roll_rows)
    lineages = sorted(by_lin.keys())
    results = []

    def try_VAR(P):
        pairs = 0; out_list = []
        for effect in lineages:
            for cause in lineages:
                if effect == cause: continue
                A = by_lin.get(effect); B = by_lin.get(cause)
                AB = align_pair_3(A, B, P=P, min_len=14 if P==3 else 12)
                if AB is None: continue
                pairs += 1
                res = block_granger_VAR(*AB, P=P)
                if res is None: continue
                out_list.append({"cause": cause, "effect": effect, "P": P, **res})
        return pairs, out_list

    pairs3, out3 = try_VAR(P=3)
    if out3:
        used_P = 3; out = out3; pairs = pairs3
    else:
        pairs2, out2 = try_VAR(P=2)
        used_P = 2; out = out2; pairs = pairs2

    # Save VAR results
    var_txt = os.path.join(ANAL_BASE, "joint_metrics_v2_8_var_granger.txt")
    var_csv = os.path.join(CSV_DIR, "joint_metrics_v2_8_var_granger.csv")
    with open(var_txt, "w", encoding="utf-8") as f:
        f.write("JOINT METRICS v2.8 — 3-var Block Granger VAR(P) on rolling per-lineage [persistence, collaboration, emergence]\n")
        f.write("System test: restricted=own lags; unrestricted=own+other-lineage lags; P tried: 3 then 2\n")
        f.write(f"Used P={used_P}; pairs tried: {pairs}; results: {len(out)}\n\n")
        f.write("cause\teffect\tP\tF\tdf1\tdf2\tpvalue\tdAIC\tsignif\n")
        for r in out:
            p = r["pvalue"]; pstr = "n.a." if p is None else f"{p:.6g}"
            Fstr = "nan" if (r["F"] is None or (isinstance(r["F"], float) and math.isnan(r["F"]))) else f"{r['F']:.6f}"
            signif = "sig(p<=0.05)" if (p is not None and p <= 0.05) else ("sig(dAIC<0)" if r["dAIC"] < 0 else "")
            f.write(f"{r['cause']}\t{r['effect']}\t{r['P']}\t{Fstr}\t{r['df1']}\t{r['df2']}\t{pstr}\t{r['dAIC']:.6f}\t{signif}\n")

    with open(var_csv, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(["cause","effect","P","F","df1","df2","pvalue","dAIC"])
        for r in out:
            w.writerow([r["cause"], r["effect"], r["P"], r["F"], r["df1"], r["df2"], r["pvalue"], r["dAIC"]])

    print("V2_8_DONE", roll_csv, var_txt, var_csv, "PAIRS", len(out))
    return 0

if __name__ == "__main__":
    import sys
    try:
        sys.exit(main())
    except Exception as e:
        print("ERROR", str(e))
        sys.exit(1)
